from django.test import TestCase
from django.urls import reverse

from .models import Category, Item


class ItemViewTests(TestCase):
    @classmethod
    def setUpTestData(cls):
        category = Category.objects.create(name="Lab")
        Item.objects.create(
            name="Microscope",
            price="19.99",
            quantity=1,
            category=category,
        )

    def test_list_returns_items(self):
        response = self.client.get(reverse("item-list"))
        self.assertEqual(response.status_code, 200)
        self.assertEqual(response.json()["items"][0]["name"], "Microscope")

    def test_list_uses_one_query_for_categories(self):
        with self.assertNumQueries(1):
            self.client.get(reverse("item-list"))

    def test_missing_item_returns_404(self):
        response = self.client.get(reverse("item-detail", args=[99]))
        self.assertEqual(response.status_code, 404)
